using System;using System.Linq;using System.Collections.Generic;using System.Drawing;using System.Threading.Tasks;using System.Windows.Forms;
sealed class LandDialog:Form {
 readonly CampaignEngine engine;readonly uint actor;readonly bool mock;readonly List<CatalogItem> all;readonly HashSet<string> selected;List<CatalogItem> visible;readonly CheckedListBox list=new CheckedListBox();readonly TextBox query=Theme.Input();readonly ComboBox mode=new ComboBox();readonly Label status=Theme.Label("",9);Button load,done;bool busy;public List<string> Choice;
 public LandDialog(CampaignEngine e,uint id,IEnumerable<string> prior,bool mock){engine=e;actor=id;this.mock=mock;all=e.Catalogs["title"].Where(x=>x.id.StartsWith("c_")).ToList();visible=all;selected=new HashSet<string>(prior);Text=Lang.T("Отмеченные графства · до 100 за одну операцию");BackColor=Theme.Bg;ForeColor=Theme.Text;Font=new Font("Segoe UI",10);ClientSize=new Size(920,700);MinimumSize=Size;StartPosition=FormStartPosition.CenterParent;query.SetBounds(20,20,510,30);mode.SetBounds(545,20,215,30);mode.DropDownStyle=ComboBoxStyle.DropDownList;mode.Items.AddRange(new object[]{Lang.T("Все графства"),Lang.T("Моя держава"),Lang.T("Пограничные графства"),Lang.T("По культуре"),Lang.T("По вере")});mode.SelectedIndex=0;load=Theme.Button(Lang.T("Прочитать"),async delegate{await Read();});load.SetBounds(770,16,130,36);list.SetBounds(20,65,880,510);list.BackColor=Theme.Panel;list.ForeColor=Theme.Text;list.BorderStyle=BorderStyle.None;list.CheckOnClick=true;list.IntegralHeight=false;list.ItemHeight=25;status.SetBounds(20,585,880,30);var mark=Theme.Button(Lang.T("Отметить показанные"),delegate{foreach(var x in ShownItems().Take(Math.Max(0,100-selected.Count)))selected.Add(x.id);Filter();});mark.SetBounds(20,630,235,40);var clear=Theme.Button(Lang.T("Снять отметки"),delegate{selected.Clear();Filter();});clear.SetBounds(265,630,200,40);done=Theme.Button(Lang.T("Использовать выбранные"),delegate{Choice=selected.OrderBy(x=>x).ToList();DialogResult=DialogResult.OK;Close();},true);done.SetBounds(570,630,330,40);Controls.AddRange(new Control[]{query,mode,load,list,status,mark,clear,done});query.TextChanged+=delegate{Filter();};list.ItemCheck+=delegate(object sender,ItemCheckEventArgs a){var item=list.Items[a.Index] as CatalogItem;if(item==null)return;if(a.NewValue==CheckState.Checked){if(selected.Count>=100 && !selected.Contains(item.id)){a.NewValue=CheckState.Unchecked;status.Text=Lang.T("За одну операцию допускается 100 графств.");}else selected.Add(item.id);}else selected.Remove(item.id);};FormClosing+=delegate(object sender,FormClosingEventArgs a){if(busy)a.Cancel=true;};Filter();}
 IEnumerable<CatalogItem> ShownItems(){string q=query.Text.Trim();return visible.Where(x=>(x.name+" "+x.id).IndexOf(q,StringComparison.OrdinalIgnoreCase)>=0).Take(2000);}
 void Filter(){list.BeginUpdate();list.Items.Clear();foreach(var x in ShownItems())list.Items.Add(x,selected.Contains(x.id));list.EndUpdate();status.Text=Lang.T("В выборке: ")+visible.Count+Lang.T(" · показано: ")+list.Items.Count+Lang.T(" · отмечено: ")+selected.Count;}
 async Task Read(){if(busy)return;if(mode.SelectedIndex==0){visible=all;Filter();return;}if(mock){status.Text=Lang.T("Живая выборка требует подключения к игре.");return;}string key=null,kind=mode.SelectedIndex==3?"culture":"faith";if(mode.SelectedIndex>=3)using(var d=new CatalogDialog(Lang.T("Выбор ")+kind,engine.Catalogs[kind])){if(d.ShowDialog(this)!=DialogResult.OK)return;key=d.Choice.id;}busy=true;load.Enabled=done.Enabled=false;try{string selector=mode.SelectedIndex==1?"realm":mode.SelectedIndex==2?"border":kind;var keys=await engine.SelectLand(selector,actor,key);visible=all.Where(x=>keys.Contains(x.id)).ToList();Filter();}catch(Exception x){status.Text=x.Message;}finally{busy=false;load.Enabled=done.Enabled=true;}}
}
